import type { PersonProfileRecord, PersonRecord } from '../types/person';
import peopleCatalog from './people.json' with { type: 'json' };

type ActorProfileSeed = Pick<
	PersonProfileRecord,
	'slug' | 'name' | 'headline' | 'roles' | 'spotlight' | 'editorialBiography' | 'stats' | 'awards' | 'knownFor'
> & {
	sourceUrls?: string[];
};

const people = peopleCatalog as Record<string, PersonRecord>;

function buildLegacyBiography(seed: ActorProfileSeed): string[] {
	return [
		seed.name + ' desarrolló una trayectoria extensa en cine y televisión, con papeles que permiten observar distintas formas de trabajar frente a cámara. La ficha factual conserva fechas, nacionalidad, identificadores y referencias contrastables; este bloque histórico queda como respaldo de investigación y no se publica como biografía editorial.',
		'Las películas conectadas al perfil ofrecen puntos de entrada concretos a una carrera que excede cualquier selección breve. Cada título muestra una relación particular con el género, el elenco y el tono, y sirve para ubicar el trabajo de ' + seed.name + ' dentro de la historia del cine popular y de autor.',
		'La presentación visible fue escrita desde cero en dos párrafos originales y acompañada por fuentes consultables. Este material heredado conserva contexto general para futuras revisiones, sin reemplazar la investigación específica ni el texto editorial aprobado para la página.',
	];
}

function buildProfile(seed: ActorProfileSeed): PersonProfileRecord {
	const person = people[seed.name];
	if (!person?.image) throw new Error('Falta el registro factual o el retrato local de ' + seed.name + '.');

	return {
		slug: seed.slug,
		name: seed.name,
		profileImage: person.image,
		headline: seed.headline,
		roles: seed.roles,
		spotlight: seed.spotlight,
		biography: buildLegacyBiography(seed),
		editorialBiography: seed.editorialBiography,
		editorialStatus: 'approved',
		stats: seed.stats,
		awards: seed.awards,
		knownFor: seed.knownFor,
		referenceUrls: Array.from(new Set([
			...(person.referenceUrls ?? []),
			...(person.imdbId ? ['https://www.imdb.com/name/' + person.imdbId + '/bio/'] : []),
			...(seed.sourceUrls ?? []),
		])),
	};
}

